-- Initial D1 schema and the 512 existing project profiles.
-- Applied once by Wrangler; later data edits are not overwritten.
CREATE TABLE IF NOT EXISTS wrestlers (
  id INTEGER PRIMARY KEY CHECK (id >= 0 AND id < 512),
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  name_en TEXT NOT NULL,
  rank TEXT NOT NULL,
  rank_level TEXT NOT NULL CHECK (rank_level IN ('state', 'aimag', 'sum')),
  is_demo INTEGER NOT NULL CHECK (is_demo IN (0, 1)),
  featured INTEGER NOT NULL DEFAULT 0 CHECK (featured IN (0, 1)),
  profile TEXT NOT NULL CHECK (json_valid(profile))
);

